def serialize_tree(s: str) -> str:
    """Compress a string using run-length encoding.

    Each run of consecutive identical characters is replaced by the character
    followed by its count. A count of 1 is omitted for single characters.

    Examples:
        "aaabbc" -> "a3b2c"
        "abc"    -> "abc"
        ""       -> ""

    Args:
        s: The input string to compress.

    Returns:
        The run-length encoded string.
    """
    if not s:
        return ""

    parts = []
    count = 1
    prev = s[0]

    for ch in s[1:]:
        if ch == prev:
            count += 1
        else:
            parts.append(prev if count == 1 else f"{prev}{count}")
            prev = ch
            count = 1

    parts.append(prev if count == 1 else f"{prev}{count}")
    return "".join(parts)


