# Tests
# ---------------------------------------------------------------------------
import unittest


class TestSerializeTree(unittest.TestCase):
    """Comprehensive tests for serialize_tree (run-length encoding)."""

    # Basic cases
    def test_empty_string(self):
        self.assertEqual(serialize_tree(""), "")

    def test_single_character(self):
        self.assertEqual(serialize_tree("a"), "a")

    def test_all_same_characters(self):
        self.assertEqual(serialize_tree("aaaa"), "a4")

    def test_all_different_characters(self):
        self.assertEqual(serialize_tree("abcde"), "abcde")

    # Typical compression
    def test_mixed_runs(self):
        self.assertEqual(serialize_tree("aaabbc"), "a3b2c")

    def test_multiple_runs(self):
        self.assertEqual(serialize_tree("aaabbcccdd"), "a3b2c3d2")

    def test_single_char_between_runs(self):
        self.assertEqual(serialize_tree("aaabca"), "a3bca2")

    # Run counts > 9
    def test_double_digit_run(self):
        self.assertEqual(serialize_tree("a" * 12), "a12")

    def test_triple_digit_run(self):
        self.assertEqual(serialize_tree("x" * 256), "x256")

    def test_mixed_long_and_short_runs(self):
        self.assertEqual(serialize_tree("a" * 11 + "b" + "c" * 3), "a11bc3")

    # Repeated patterns (not compressed as groups, just runs)
    def test_alternating_characters(self):
        self.assertEqual(serialize_tree("ababab"), "ababab")

    def test_repeated_pairs(self):
        self.assertEqual(serialize_tree("aabbaabb"), "a2b2a2b2")

    # Whitespace and special characters
    def test_spaces(self):
        self.assertEqual(serialize_tree("   "), " 3")

    def test_mixed_whitespace(self):
        self.assertEqual(serialize_tree("a  bb"), "a 1b2")

    def test_special_characters(self):
        self.assertEqual(serialize_tree("!!@@@"), "!2@3")

    def test_newlines_and_tabs(self):
        self.assertEqual(serialize_tree("\n\n\t\t\t"), "\n2\t3")

    # Unicode
    def test_unicode_characters(self):
        self.assertEqual(serialize_tree("aaééébb"), "a2é3b2")

    def test_emoji_runs(self):
        self.assertEqual(serialize_tree("😀😀😀🙂"), "😀3🙂")

    # Numbers as input characters
    def test_digit_characters(self):
        self.assertEqual(serialize_tree("111223"), "13223")

    # Idempotency of already-encoded strings
    def test_already_encoded(self):
        # "a3b2c" encodes to itself since there are no runs
        self.assertEqual(serialize_tree("a3b2c"), "a3b2c")

    # Boundary: two characters
    def test_two_same(self):
        self.assertEqual(serialize_tree("aa"), "a2")

    def test_two_different(self):
        self.assertEqual(serialize_tree("ab"), "ab")

    # Stress: long input
    def test_long_alternating(self):
        s = "ab" * 5000
        self.assertEqual(serialize_tree(s), s)

    def test_long_single_run(self):
        s = "z" * 10000
        self.assertEqual(serialize_tree(s), "z10000")

    # Round-trip property: encoded length <= original length
    def test_encoded_not_longer_than_input(self):
        cases = ["", "a", "aaabbc", "abcde", "a" * 100, "ab" * 50]
        for s in cases:
            self.assertLessEqual(len(serialize_tree(s)), len(s))


if __name__ == "__main__":
    unittest.main()
